          var n = next();
          if (n < 1 || n > 8) throw new Error(hint);
          fr('Inside solve(): <code>cin &gt;&gt; n</code> → <b>n = ' + n + '</b>.', L.readN, { 'test #': tc, n: n });
          var a = [];
